return new[]{"Assets/Maps/Buildings/Walls/Prefabs/Wall_Window_Static_Variant.prefab","Assets/Maps/Buildings/Walls/Prefabs/Wall_Door_Metal.prefab","Assets/Maps/Buildings/Stairs/Prefabs/Stairwell_3m_UShape.prefab"}.Select(p=> {var g=UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.GameObject>(p);return new {path=p, renderers=g.GetComponentsInChildren<UnityEngine.Renderer>(true).Where(r=>p.Contains("Door")||r.name=="Wall_Window").Select(r=>new{name=r.name,bounds=r.bounds.ToString(),materials=r.sharedMaterials.Select(m=>m?UnityEditor.AssetDatabase.GetAssetPath(m):"null").ToArray()}).ToArray(), scripts=g.GetComponentsInChildren<UnityEngine.MonoBehaviour>(true).Select(m=>m?m.GetType().Name:"MISSING").ToArray()};}).ToArray();
